import React, { Component } from 'react'

export class Items extends Component {
  render() {
    return (
        <main>
        <div className='item'>
            <img src={"./img/" + items.img} alt={items.title} />
                <h2>{items.title}</h2>
                <p>{items.desc}</p>
                <b>{items.price}$</b>
        <div className='add-to-cart'>+</div>
    </div>
        </main>
    )
  }
}

export default Items
